#!/usr/bin/env python3
"""Emit one atomic Linux thermal/throttle sysfs snapshot as compact JSON."""
import glob
import json
import os
import re
import sys
import time

CPU_ROOT = "/sys/devices/system/cpu"
THERMAL_ROOT = "/sys/class/thermal"
HWMON_ROOT = "/sys/class/hwmon"
CPU_LIST_RE = re.compile(r"^[0-9,-]+$")
TRIP_RE = re.compile(r"trip_point_([0-9]+)_temp$")
TEMP_INPUT_RE = re.compile(r"temp([0-9]+)_input$")


def text(path):
    with open(path, "r", encoding="ascii") as handle:
        return handle.read().strip()


def integer(path):
    value = int(text(path), 10)
    if value < 0:
        raise ValueError(f"negative sysfs value: {path}")
    return value


def optional_text(path):
    try:
        value = text(path)
        return value if value else None
    except (FileNotFoundError, PermissionError, OSError, UnicodeError):
        return None


def optional_int(path):
    try:
        return integer(path)
    except (FileNotFoundError, PermissionError, OSError, UnicodeError, ValueError):
        return None


def expand_cpu_list(spec):
    if not CPU_LIST_RE.fullmatch(spec or ""):
        raise ValueError(f"invalid CPU list: {spec!r}")
    result = set()
    for part in spec.split(","):
        if "-" in part:
            first, last = (int(item) for item in part.split("-", 1))
            if last < first:
                raise ValueError(f"descending CPU range: {part}")
            result.update(range(first, last + 1))
        else:
            result.add(int(part))
    return sorted(result)


def compact_cpu_list(cpus):
    return ",".join(str(cpu) for cpu in sorted(cpus))


def counter_record(scope, package_id, core_id, cpu_id, peers):
    prefix = "core" if scope == "core" else "package"
    root = os.path.join(CPU_ROOT, f"cpu{cpu_id}", "thermal_throttle")
    count_path = os.path.join(root, f"{prefix}_throttle_count")
    if not os.path.isfile(count_path):
        return None
    entity_id = f"package{package_id}" if scope == "package" else f"package{package_id}/core{core_id}"
    return {
        "scope": scope,
        "entity_id": entity_id,
        "package_id": package_id,
        "core_id": core_id if scope == "core" else None,
        "representative_cpu": cpu_id,
        "peer_cpu_list": compact_cpu_list(peers),
        "throttle_count_total": integer(count_path),
        "throttle_total_time_ms": optional_int(os.path.join(root, f"{prefix}_throttle_total_time_ms")),
        "throttle_max_time_ms": optional_int(os.path.join(root, f"{prefix}_throttle_max_time_ms")),
    }


def collect_counters(cpus):
    topology = {}
    for cpu in cpus:
        root = os.path.join(CPU_ROOT, f"cpu{cpu}")
        if not os.path.isdir(os.path.join(root, "thermal_throttle")):
            continue
        topology[cpu] = (
            integer(os.path.join(root, "topology", "physical_package_id")),
            integer(os.path.join(root, "topology", "core_id")),
        )
    records = []
    packages = sorted({package for package, _ in topology.values()})
    cores = sorted(set(topology.values()))
    for package in packages:
        peers = [cpu for cpu, ids in topology.items() if ids[0] == package]
        record = counter_record("package", package, None, min(peers), peers)
        if record:
            records.append(record)
    for package, core in cores:
        peers = [cpu for cpu, ids in topology.items() if ids == (package, core)]
        record = counter_record("core", package, core, min(peers), peers)
        if record:
            records.append(record)
    return records


def collect_zones(errors):
    zones = []
    for path in sorted(glob.glob(os.path.join(THERMAL_ROOT, "thermal_zone[0-9]*"))):
        try:
            trips = []
            for trip_path in sorted(glob.glob(os.path.join(path, "trip_point_*_temp"))):
                match = TRIP_RE.search(os.path.basename(trip_path))
                if not match:
                    continue
                index = int(match.group(1))
                trip_type = optional_text(os.path.join(path, f"trip_point_{index}_type"))
                trip_temp = optional_int(trip_path)
                if trip_type is not None and trip_temp is not None:
                    trips.append({"index": index, "type": trip_type, "temp_millic": trip_temp, "hysteresis_celsius": optional_int(os.path.join(path, f"trip_point_{index}_hyst"))})
            zones.append({"zone_id": os.path.basename(path), "zone_type": text(os.path.join(path, "type")), "temp_millic": integer(os.path.join(path, "temp")), "mode": optional_text(os.path.join(path, "mode")), "policy": optional_text(os.path.join(path, "policy")), "trips": trips})
        except (OSError, UnicodeError, ValueError) as exc:
            errors.append({"surface": "thermal_zone", "entity": os.path.basename(path), "error_class": type(exc).__name__})
    return zones


def collect_cooling(errors):
    devices = []
    for path in sorted(glob.glob(os.path.join(THERMAL_ROOT, "cooling_device[0-9]*"))):
        try:
            devices.append({"cooling_id": os.path.basename(path), "cooling_type": text(os.path.join(path, "type")), "cur_state": integer(os.path.join(path, "cur_state")), "max_state": integer(os.path.join(path, "max_state"))})
        except (OSError, UnicodeError, ValueError) as exc:
            errors.append({"surface": "cooling_device", "entity": os.path.basename(path), "error_class": type(exc).__name__})
    return devices


def collect_hwmon(errors):
    channels = []
    for hwmon in sorted(glob.glob(os.path.join(HWMON_ROOT, "hwmon[0-9]*"))):
        name = optional_text(os.path.join(hwmon, "name")) or "unknown"
        for input_path in sorted(glob.glob(os.path.join(hwmon, "temp*_input"))):
            match = TEMP_INPUT_RE.search(os.path.basename(input_path))
            if not match:
                continue
            channel = int(match.group(1))
            try:
                alarms = {}
                for alarm_path in glob.glob(os.path.join(hwmon, f"temp{channel}*_alarm")):
                    alarms[os.path.basename(alarm_path)] = integer(alarm_path)
                channels.append({"hwmon_id": os.path.basename(hwmon), "hwmon_name": name, "device_path": os.path.realpath(hwmon), "channel": channel, "label": optional_text(os.path.join(hwmon, f"temp{channel}_label")), "input_raw": integer(input_path), "unit_contract": "millidegree_celsius_unless_driver_documents_millivolt", "max_raw": optional_int(os.path.join(hwmon, f"temp{channel}_max")), "crit_raw": optional_int(os.path.join(hwmon, f"temp{channel}_crit")), "emergency_raw": optional_int(os.path.join(hwmon, f"temp{channel}_emergency")), "fault": optional_int(os.path.join(hwmon, f"temp{channel}_fault")), "alarms": alarms})
            except (OSError, UnicodeError, ValueError) as exc:
                errors.append({"surface": "hwmon", "entity": f"{os.path.basename(hwmon)}/temp{channel}", "error_class": type(exc).__name__})
    return channels


def emit(event):
    print(json.dumps(event, separators=(",", ":"), sort_keys=False), flush=True)


def main():
    sample_epoch = int(time.time())
    base = {"schema_version": 1, "record_type": "snapshot", "collector": "linux_thermal_sysfs_v1", "sample_epoch": sample_epoch}
    try:
        boot_id = text("/proc/sys/kernel/random/boot_id")
        online_before = text(os.path.join(CPU_ROOT, "online"))
        cpus = expand_cpu_list(online_before)
        counters = collect_counters(cpus)
        if not counters:
            base.update({"record_type": "status", "collector_status": "unsupported", "boot_id": boot_id, "reason": "no documented Intel thermal_throttle count files on online CPUs"})
            emit(base)
            return 0
        errors = []
        zones = collect_zones(errors)
        cooling = collect_cooling(errors)
        hwmon = collect_hwmon(errors)
        online_after = text(os.path.join(CPU_ROOT, "online"))
        if online_before != online_after:
            raise RuntimeError("online CPU topology changed during collection")
        hottest = max(zones, key=lambda item: item["temp_millic"], default=None)
        trip_candidates = [(trip["temp_millic"] - zone["temp_millic"], zone, trip) for zone in zones for trip in zone["trips"] if trip["type"] in {"passive", "hot", "critical"}]
        nearest = min(trip_candidates, key=lambda item: item[0], default=None)
        active_alarms = sum(1 for channel in hwmon for value in channel["alarms"].values() if value == 1)
        base.update({
            "collector_status": "ok",
            "snapshot_id": f"{boot_id}:{time.monotonic_ns()}",
            "boot_id": boot_id,
            "online_cpu_list": online_before,
            "throttle_counter_count": len(counters),
            "throttle_counters": counters,
            "thermal_zone_count": len(zones),
            "thermal_zones": zones,
            "cooling_device_count": len(cooling),
            "cooling_devices": cooling,
            "hwmon_temperature_count": len(hwmon),
            "hwmon_temperatures": hwmon,
            "hottest_thermal_zone_id": hottest["zone_id"] if hottest else None,
            "hottest_thermal_zone_type": hottest["zone_type"] if hottest else None,
            "hottest_thermal_zone_temp_millic": hottest["temp_millic"] if hottest else None,
            "nearest_zone_trip_type": nearest[2]["type"] if nearest else None,
            "nearest_zone_trip_temp_millic": nearest[2]["temp_millic"] if nearest else None,
            "nearest_zone_trip_headroom_millic": nearest[0] if nearest else None,
            "active_cooling_device_count": sum(1 for item in cooling if item["cur_state"] > 0),
            "active_hwmon_alarm_count": active_alarms,
            "context_error_count": len(errors),
            "context_errors": errors,
        })
        emit(base)
        return 0
    except Exception as exc:
        base.update({"record_type": "status", "collector_status": "error", "error_class": type(exc).__name__, "error_reason": str(exc)[:256]})
        emit(base)
        print(f"thermal collection failed: {type(exc).__name__}: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
